import React, { useState } from 'react';
import { OrbMain } from '../components/Orb';
import { BtnPrimary, BtnSmall, BtnSecondary } from '../components/GlassButton';
import { analyzeThought } from '../hooks/useGroq';
import { useThoughts } from '../hooks/useStorage';

export default function Home({ setPage, streak }) {
  const [open,    setOpen]    = useState(false);
  const [text,    setText]    = useState('');
  const [loading, setLoading] = useState(false);
  const [error,   setError]   = useState('');
  const [result,  setResult]  = useState(null);
  const { addThought } = useThoughts();

  const submit = async () => {
    if (!text.trim() || loading) return;
    setLoading(true); setError('');
    try {
      const ai = await analyzeThought(text);
      const entry = { id: Date.now(), user_text: text, ...ai, date: new Date().toISOString() };
      addThought(entry);
      setResult(entry);
      setOpen(false);
    } catch { setError('Something went wrong. Try again.'); }
    setLoading(false);
  };

  if (result) return <Analysis result={result} text={text} onBack={() => { setResult(null); setText(''); }} setPage={setPage} />;

  return (
    <div style={{ position: 'relative', minHeight: '100vh', background: '#0F1C1C', overflow: 'hidden' }}>
      <OrbMain />

      {loading && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 250, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', gap: 18, background: 'rgba(15,28,28,0.82)', backdropFilter: 'blur(12px)' }}>
          <div style={{ width: 64, height: 64, borderRadius: '50%', background: 'radial-gradient(circle at 38% 35%, #7EC8C8, #2D6B6B)', animation: 'loadPulse 1.2s ease-in-out infinite' }} />
          <p style={{ fontSize: 13, fontWeight: 500, color: 'rgba(238,234,227,0.38)' }}>Analysing…</p>
        </div>
      )}

      <div style={{ position: 'relative', zIndex: 10, display: 'flex', flexDirection: 'column', justifyContent: 'space-between', minHeight: '100vh', padding: '52px 24px 108px' }}>

        {/* Top */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span style={{ fontSize: 12, fontWeight: 600, letterSpacing: '-0.02em', color: 'rgba(238,234,227,0.28)' }}>spiral</span>
          {streak > 0 && (
            <div style={{ padding: '6px 12px', borderRadius: 999, background: 'rgba(255,255,255,0.07)', boxShadow: '0 1px 0 rgba(255,255,255,0.1) inset, 0 0 0 1px rgba(255,255,255,0.08)', fontSize: 11, fontWeight: 600, color: '#7EC8C8' }}>
              🔥 {streak} {streak === 1 ? 'day' : 'days'}
            </div>
          )}
        </div>

        {/* Headline */}
        <div style={{ animation: 'fadeIn 0.7s 0.15s both' }}>
          <h1 style={{ fontSize: 40, fontWeight: 700, letterSpacing: '-0.055em', lineHeight: 1.01, color: '#EEEAE3' }}>
            Break<br />the <span style={{ color: '#7EC8C8' }}>spiral.</span>
          </h1>
          <p style={{ fontSize: 13, color: 'rgba(238,234,227,0.32)', marginTop: 10, lineHeight: 1.65, maxWidth: 210 }}>
            Write down the thought. AI identifies the pattern.
          </p>
        </div>

        {/* Actions */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 10, animation: 'fadeIn 0.7s 0.3s both' }}>
          <div style={{ display: 'flex', gap: 10 }}>
            <BtnSmall
              onClick={() => setPage('checkin')}
              icon={<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="9"/><path d="M8 12l3 3 5-5"/></svg>}
            >
              Check-in
            </BtnSmall>
            <BtnSmall
              onClick={() => setPage('breathing')}
              icon={<svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><path d="M12 4c0 0-4 3-4 7s4 5 4 9"/><path d="M12 4c0 0 4 3 4 7s-4 5-4 9"/></svg>}
            >
              Breathe
            </BtnSmall>
          </div>
          <BtnPrimary onClick={() => setOpen(true)}>New thought</BtnPrimary>
        </div>
      </div>

      {/* Input sheet */}
      {open && (
        <div style={{ position: 'absolute', inset: 0, zIndex: 200, display: 'flex', flexDirection: 'column', justifyContent: 'flex-end', background: 'rgba(0,0,0,0.45)', backdropFilter: 'blur(6px)', animation: 'fadeIn 0.25s ease' }}>
          <div onClick={() => setOpen(false)} style={{ flex: 1 }} />
          <div style={{ margin: '0 10px 12px', borderRadius: 30, padding: '26px 22px 22px', background: 'rgba(15,28,28,0.97)', boxShadow: '0 1px 0 rgba(255,255,255,0.1) inset, 0 0 0 1px rgba(255,255,255,0.08), 0 -8px 60px rgba(0,0,0,0.4)', animation: 'slideUp 0.38s cubic-bezier(0.16,1,0.3,1)', position: 'relative' }}>
            <button onClick={() => setOpen(false)} style={{ position: 'absolute', top: 22, right: 22, width: 28, height: 28, borderRadius: '50%', background: 'rgba(255,255,255,0.08)', color: 'rgba(238,234,227,0.4)', fontSize: 13, display: 'flex', alignItems: 'center', justifyContent: 'center', border: 'none', cursor: 'pointer' }}>✕</button>
            <div style={{ fontSize: 10, fontWeight: 700, color: 'rgba(238,234,227,0.25)', letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: 13 }}>What's on your mind?</div>
            <textarea autoFocus value={text} onChange={e => setText(e.target.value)} maxLength={1000} placeholder="Write freely…" style={{ width: '100%', minHeight: 110, background: 'transparent', border: 'none', outline: 'none', fontSize: 17, lineHeight: 1.65, color: '#EEEAE3', resize: 'none', fontFamily: "'Inter', sans-serif" }} />
            <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', paddingTop: 14, borderTop: '1px solid rgba(255,255,255,0.07)', marginTop: 4 }}>
              <span style={{ fontSize: 11, color: 'rgba(238,234,227,0.2)' }}>{text.length} / 1000</span>
              <BtnPrimary onClick={submit} disabled={!text.trim() || loading} style={{ width: 'auto', padding: '11px 22px', fontSize: 13 }}>Analyse →</BtnPrimary>
            </div>
            {error && <p style={{ fontSize: 12, color: 'rgba(220,100,100,0.8)', marginTop: 10 }}>{error}</p>}
          </div>
        </div>
      )}
    </div>
  );
}

function Analysis({ result, text, onBack, setPage }) {

  return (
    <div style={{ background: '#0F1C1C', minHeight: '100vh', overflowY: 'auto', position: 'relative' }}>
      <div style={{ position: 'fixed', left: '50%', transform: 'translateX(-50%)', width: 360, height: 360, top: 80, borderRadius: '50%', background: 'radial-gradient(circle at 40% 40%, rgba(200,100,80,0.18) 0%, rgba(100,40,30,0.07) 55%, transparent 75%)', filter: 'blur(32px)', pointerEvents: 'none', zIndex: 0 }} />
      <div style={{ padding: '56px 24px 110px', position: 'relative', zIndex: 1 }}>
        <button onClick={onBack} style={{ fontSize: 13, fontWeight: 500, color: '#7EC8C8', marginBottom: 32, display: 'block', background: 'none', border: 'none', cursor: 'pointer', padding: 0 }}>← Back</button>
        <div style={{ display: 'inline-flex', alignItems: 'center', gap: 7, padding: '7px 14px', borderRadius: 999, background: 'rgba(126,200,200,0.1)', boxShadow: '0 0 0 1px rgba(126,200,200,0.2)', marginBottom: 14 }}>
          <div style={{ width: 6, height: 6, borderRadius: '50%', background: '#7EC8C8' }} />
          <span style={{ fontSize: 11, fontWeight: 700, color: '#7EC8C8', letterSpacing: '0.06em', textTransform: 'uppercase' }}>{result.trap_label}</span>
        </div>
        <h2 style={{ fontSize: 32, fontWeight: 700, letterSpacing: '-0.05em', lineHeight: 1.04, color: '#EEEAE3', marginBottom: 22 }}>{result.trap_label}.</h2>
        <div style={{ padding: '16px 18px', borderLeft: '2px solid #7EC8C8', background: 'rgba(126,200,200,0.06)', borderRadius: '0 14px 14px 0', marginBottom: 18 }}>
          <p style={{ fontSize: 14, lineHeight: 1.7, color: 'rgba(238,234,227,0.42)', fontStyle: 'italic' }}>"{text.slice(0, 120)}{text.length > 120 ? '…' : ''}"</p>
        </div>
        {[['What\'s happening', result.description], ['Reframe', result.reframe], ['Exercise', result.exercise_text]].map(([lbl, body]) => (
          <div key={lbl} style={{ padding: 18, borderRadius: 20, marginBottom: 10, background: 'rgba(255,255,255,0.05)', boxShadow: '0 1px 0 rgba(255,255,255,0.08) inset, 0 0 0 1px rgba(255,255,255,0.06)' }}>
            <div style={{ fontSize: 10, fontWeight: 700, color: '#7EC8C8', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 7 }}>{lbl}</div>
            <p style={{ fontSize: 15, lineHeight: 1.7, color: 'rgba(238,234,227,0.72)', fontWeight: 400 }}>{body}</p>
          </div>
        ))}
        <button onClick={() => setPage('breathing')} style={{ width: '100%', padding: 16, borderRadius: 999, marginTop: 8, border: 'none', color: 'rgba(238,234,227,0.6)', fontSize: 14, fontWeight: 500, cursor: 'pointer', fontFamily: "'Inter', sans-serif", background: 'linear-gradient(160deg, rgba(255,255,255,0.09) 0%, rgba(255,255,255,0.04) 100%)', boxShadow: '0 1px 0 rgba(255,255,255,0.12) inset, 0 0 0 1px rgba(255,255,255,0.07)' }}>
          Breathing exercise →
        </button>
      </div>
    </div>
  );
}
